-- MERQO CoachDesk PostgreSQL production baseline
-- This migration is not executed by the current Linux sandbox because PostgreSQL
-- tools/server are unavailable. UUIDs are generated by the application service;
-- no database extension is required by this baseline.

BEGIN;

CREATE TABLE IF NOT EXISTS schema_migrations (
  version VARCHAR(40) PRIMARY KEY,
  applied_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS institutions (
  id UUID PRIMARY KEY,
  name TEXT NOT NULL,
  name_bn TEXT,
  email TEXT,
  address TEXT,
  address_bn TEXT,
  currency_code CHAR(3) NOT NULL DEFAULT 'BDT',
  timezone TEXT NOT NULL DEFAULT 'Asia/Dhaka',
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS branches (
  id UUID PRIMARY KEY,
  institution_id UUID NOT NULL REFERENCES institutions(id),
  branch_code TEXT NOT NULL,
  name TEXT NOT NULL,
  name_bn TEXT,
  address TEXT,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  UNIQUE (institution_id, branch_code)
);
CREATE INDEX IF NOT EXISTS ix_branches_institution ON branches(institution_id);

CREATE TABLE IF NOT EXISTS users (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  username TEXT NOT NULL,
  display_name TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  UNIQUE (branch_id, username)
);
CREATE INDEX IF NOT EXISTS ix_users_branch_active ON users(branch_id, active);

CREATE TABLE IF NOT EXISTS roles (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  UNIQUE (branch_id, code)
);
CREATE TABLE IF NOT EXISTS permissions (
  id UUID PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  description TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS user_roles (
  user_id UUID NOT NULL REFERENCES users(id),
  role_id UUID NOT NULL REFERENCES roles(id),
  PRIMARY KEY (user_id, role_id)
);
CREATE TABLE IF NOT EXISTS role_permissions (
  role_id UUID NOT NULL REFERENCES roles(id),
  permission_id UUID NOT NULL REFERENCES permissions(id),
  PRIMARY KEY (role_id, permission_id)
);

CREATE TABLE IF NOT EXISTS academic_years (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  starts_on DATE NOT NULL,
  ends_on DATE NOT NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  CHECK (ends_on >= starts_on),
  UNIQUE (branch_id, code)
);

CREATE TABLE IF NOT EXISTS courses (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  name_bn TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'archived')),
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  UNIQUE (branch_id, code)
);
CREATE TABLE IF NOT EXISTS subjects (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  name_bn TEXT,
  UNIQUE (branch_id, code)
);
CREATE TABLE IF NOT EXISTS course_subjects (
  course_id UUID NOT NULL REFERENCES courses(id),
  subject_id UUID NOT NULL REFERENCES subjects(id),
  display_order INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (course_id, subject_id)
);
CREATE TABLE IF NOT EXISTS batches (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  course_id UUID NOT NULL REFERENCES courses(id),
  academic_year_id UUID NOT NULL REFERENCES academic_years(id),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  starts_on DATE,
  ends_on DATE,
  capacity INTEGER CHECK (capacity IS NULL OR capacity > 0),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'archived')),
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  UNIQUE (branch_id, code)
);
CREATE INDEX IF NOT EXISTS ix_batches_course_year ON batches(course_id, academic_year_id);

CREATE TABLE IF NOT EXISTS students (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  student_id TEXT NOT NULL,
  name_bn TEXT NOT NULL,
  name_en TEXT,
  date_of_birth DATE,
  gender TEXT,
  phone TEXT,
  address TEXT,
  admission_source TEXT,
  notes TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'archived', 'withdrawn')),
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  created_by UUID NOT NULL REFERENCES users(id),
  updated_by UUID NOT NULL REFERENCES users(id),
  UNIQUE (branch_id, student_id)
);
CREATE INDEX IF NOT EXISTS ix_students_branch_name ON students(branch_id, name_bn);
CREATE INDEX IF NOT EXISTS ix_students_branch_phone ON students(branch_id, phone);

CREATE TABLE IF NOT EXISTS guardians (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  name TEXT NOT NULL,
  phone TEXT,
  address TEXT,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL
);
CREATE TABLE IF NOT EXISTS student_guardians (
  student_id UUID NOT NULL REFERENCES students(id),
  guardian_id UUID NOT NULL REFERENCES guardians(id),
  relationship TEXT NOT NULL,
  is_primary BOOLEAN NOT NULL DEFAULT FALSE,
  is_emergency BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY (student_id, guardian_id)
);

CREATE TABLE IF NOT EXISTS enrollments (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  student_id UUID NOT NULL REFERENCES students(id),
  batch_id UUID NOT NULL REFERENCES batches(id),
  academic_year_id UUID NOT NULL REFERENCES academic_years(id),
  enrollment_code TEXT NOT NULL,
  admission_date DATE NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'completed', 'withdrawn', 'cancelled')),
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  created_by UUID NOT NULL REFERENCES users(id),
  UNIQUE (branch_id, enrollment_code),
  UNIQUE (student_id, batch_id, academic_year_id)
);
CREATE INDEX IF NOT EXISTS ix_enrollments_student ON enrollments(student_id, status);
CREATE INDEX IF NOT EXISTS ix_enrollments_batch ON enrollments(batch_id, status);

CREATE TABLE IF NOT EXISTS fee_types (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  name_bn TEXT,
  UNIQUE (branch_id, code)
);
CREATE TABLE IF NOT EXISTS fee_plans (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  course_id UUID REFERENCES courses(id),
  academic_year_id UUID REFERENCES academic_years(id),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  UNIQUE (branch_id, code)
);
CREATE TABLE IF NOT EXISTS fee_plan_items (
  id UUID PRIMARY KEY,
  fee_plan_id UUID NOT NULL REFERENCES fee_plans(id),
  fee_type_id UUID NOT NULL REFERENCES fee_types(id),
  title TEXT NOT NULL,
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  due_offset_days INTEGER,
  display_order INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS fee_assignments (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  enrollment_id UUID NOT NULL REFERENCES enrollments(id),
  fee_plan_id UUID REFERENCES fee_plans(id),
  assigned_at TIMESTAMPTZ NOT NULL,
  approved_discount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (approved_discount >= 0),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'replaced', 'cancelled'))
);
CREATE TABLE IF NOT EXISTS invoices (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  enrollment_id UUID NOT NULL REFERENCES enrollments(id),
  invoice_number TEXT NOT NULL,
  issued_on DATE NOT NULL,
  due_on DATE,
  status TEXT NOT NULL DEFAULT 'posted' CHECK (status IN ('draft', 'posted', 'voided')),
  created_at TIMESTAMPTZ NOT NULL,
  created_by UUID NOT NULL REFERENCES users(id),
  UNIQUE (branch_id, invoice_number)
);
CREATE TABLE IF NOT EXISTS invoice_items (
  id UUID PRIMARY KEY,
  invoice_id UUID NOT NULL REFERENCES invoices(id),
  fee_type_id UUID REFERENCES fee_types(id),
  title TEXT NOT NULL,
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  allocated_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (allocated_amount >= 0 AND allocated_amount <= amount),
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'partially_paid', 'paid', 'waived'))
);
CREATE INDEX IF NOT EXISTS ix_invoice_items_invoice ON invoice_items(invoice_id, status);

CREATE TABLE IF NOT EXISTS payments (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  receipt_number TEXT NOT NULL,
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  method TEXT NOT NULL,
  reference TEXT,
  idempotency_key TEXT NOT NULL,
  posted_at TIMESTAMPTZ NOT NULL,
  posted_by UUID NOT NULL REFERENCES users(id),
  UNIQUE (branch_id, receipt_number),
  UNIQUE (branch_id, idempotency_key)
);
CREATE TABLE IF NOT EXISTS payment_allocations (
  id UUID PRIMARY KEY,
  payment_id UUID NOT NULL REFERENCES payments(id),
  invoice_item_id UUID NOT NULL REFERENCES invoice_items(id),
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  created_at TIMESTAMPTZ NOT NULL,
  UNIQUE (payment_id, invoice_item_id)
);
CREATE INDEX IF NOT EXISTS ix_payment_allocations_item ON payment_allocations(invoice_item_id);

CREATE TABLE IF NOT EXISTS refunds (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  payment_id UUID NOT NULL REFERENCES payments(id),
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  reason TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'approved' CHECK (status IN ('requested', 'approved', 'posted', 'cancelled')),
  approved_by UUID REFERENCES users(id),
  posted_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL,
  created_by UUID NOT NULL REFERENCES users(id)
);
CREATE TABLE IF NOT EXISTS adjustments (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  invoice_item_id UUID REFERENCES invoice_items(id),
  payment_id UUID REFERENCES payments(id),
  amount NUMERIC(12,2) NOT NULL,
  adjustment_type TEXT NOT NULL CHECK (adjustment_type IN ('discount', 'waiver', 'correction', 'reversal')),
  reason TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  created_by UUID NOT NULL REFERENCES users(id),
  approved_by UUID REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS expense_categories (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  UNIQUE (branch_id, code)
);
CREATE TABLE IF NOT EXISTS expenses (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  category_id UUID NOT NULL REFERENCES expense_categories(id),
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  payment_method TEXT NOT NULL,
  description TEXT NOT NULL,
  expense_date DATE NOT NULL,
  status TEXT NOT NULL DEFAULT 'posted' CHECK (status IN ('draft', 'posted', 'voided')),
  created_at TIMESTAMPTZ NOT NULL,
  created_by UUID NOT NULL REFERENCES users(id)
);
CREATE TABLE IF NOT EXISTS cash_sessions (
  id UUID PRIMARY KEY,
  branch_id UUID NOT NULL REFERENCES branches(id),
  user_id UUID NOT NULL REFERENCES users(id),
  opened_at TIMESTAMPTZ NOT NULL,
  opening_balance NUMERIC(12,2) NOT NULL CHECK (opening_balance >= 0),
  closed_at TIMESTAMPTZ,
  expected_closing NUMERIC(12,2),
  actual_closing NUMERIC(12,2),
  variance NUMERIC(12,2),
  notes TEXT,
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed', 'reviewed'))
);

CREATE TABLE IF NOT EXISTS audit_logs (
  id UUID PRIMARY KEY,
  branch_id UUID REFERENCES branches(id),
  actor_user_id UUID REFERENCES users(id),
  action TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_id UUID,
  occurred_at TIMESTAMPTZ NOT NULL,
  before_json JSONB,
  after_json JSONB,
  request_id TEXT
);
CREATE INDEX IF NOT EXISTS ix_audit_branch_time ON audit_logs(branch_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS ix_audit_entity ON audit_logs(entity_type, entity_id);

INSERT INTO schema_migrations (version) VALUES ('001_initial') ON CONFLICT (version) DO NOTHING;
COMMIT;
